# 상태 집합 R, 전이 T는 BDD로 표현 (개별 열거 없음)
def image(R, T):  # R에서 한 단계 후 상태 집합
    return exists_current(R & T).rename_next_to_current()

def check_invariant(init, T, bad):
    R = init
    while True:
        if not (R & bad).is_empty():
            return 'violated'  # 반례 존재
        nxt = R | image(R, T)
        if nxt == R:  # 고정점: 더 이상 새 상태 없음
            return 'holds'
        R = nxt
